void IExecuteFencedInfoCallbackAsyncWaiter::getExecuteFencedInfo(
    android::nn::GeneralError* out_status, android::nn::Timing* out_timingLaunched, android::nn::Timing* out_timingFenced) {
  base::RunLoop loop;
  proxy_->getExecuteFencedInfo(
      base::BindOnce(
          [](base::RunLoop* loop,
             android::nn::GeneralError* out_status
,
             android::nn::Timing* out_timingLaunched
,
             android::nn::Timing* out_timingFenced
,
             android::nn::GeneralError status,
             android::nn::Timing timingLaunched,
             android::nn::Timing timingFenced) {*out_status = std::move(status);*out_timingLaunched = std::move(timingLaunched);*out_timingFenced = std::move(timingFenced);
            loop->Quit();
          },
          &loop,
          out_status,
          out_timingLaunched,
          out_timingFenced));
  loop.Run();
}








